import { MakeLogicType, actions, beforeUnmount, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { BrowserKernelClient } from './BrowserKernelClient'
import type { BrowserKernelFrame } from './browserKernelProtocol'

export type BrowserKernelStatus = 'stopped' | 'starting' | 'ready' | 'busy' | 'error'

export type NotebookBrowserKernelLogicProps = {
    shortId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookBrowserKernelLogicValues {
    canInterrupt: boolean
    error: string | null
    frames: BrowserKernelFrame[]
    isRunning: boolean
    outputFrameNames: Set<string>
    progress: string | null
    status: BrowserKernelStatus
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookBrowserKernelLogicActions {
    kernelFailed: (error: string) => {
        error: string
    }
    kernelStarted: (canInterrupt: boolean) => {
        canInterrupt: boolean
    }
    restartKernel: () => {
        value: true
    }
    runFinished: () => {
        value: true
    }
    runStarted: () => {
        value: true
    }
    setFrames: (frames: BrowserKernelFrame[]) => {
        frames: BrowserKernelFrame[]
    }
    setProgress: (progress: string | null) => {
        progress: string | null
    }
    startKernel: () => {
        value: true
    }
    stopKernel: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface notebookBrowserKernelLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        isRunning: (status: BrowserKernelStatus) => boolean
        outputFrameNames: (frames: BrowserKernelFrame[]) => Set<string>
    }
}

export type notebookBrowserKernelLogicType = MakeLogicType<
    notebookBrowserKernelLogicValues,
    notebookBrowserKernelLogicActions,
    NotebookBrowserKernelLogicProps,
    notebookBrowserKernelLogicMeta
>

/**
 * One notebook's Python kernel in this tab. The kernel lives as long as the notebook stays open:
 * cells connect to this logic, so leaving the notebook unmounts it and frees the worker's memory.
 */
export const notebookBrowserKernelLogic = kea<notebookBrowserKernelLogicType>([
    path((key) => ['scenes', 'notebooks', 'Notebook', 'browserKernel', 'notebookBrowserKernelLogic', key]),
    props({} as NotebookBrowserKernelLogicProps),
    key((props) => props.shortId),
    actions({
        startKernel: true,
        restartKernel: true,
        stopKernel: true,
        kernelStarted: (canInterrupt: boolean) => ({ canInterrupt }),
        kernelFailed: (error: string) => ({ error }),
        setProgress: (progress: string | null) => ({ progress }),
        setFrames: (frames: BrowserKernelFrame[]) => ({ frames }),
        runStarted: true,
        runFinished: true,
    }),
    reducers({
        status: [
            'stopped' as BrowserKernelStatus,
            {
                startKernel: (state) => (state === 'stopped' || state === 'error' ? 'starting' : state),
                restartKernel: () => 'starting',
                stopKernel: () => 'stopped',
                kernelStarted: () => 'ready',
                kernelFailed: () => 'error',
                runStarted: (state) => (state === 'ready' ? 'busy' : state),
                runFinished: (state) => (state === 'busy' ? 'ready' : state),
            },
        ],
        error: [
            null as string | null,
            {
                startKernel: () => null,
                restartKernel: () => null,
                kernelFailed: (_, { error }) => error,
            },
        ],
        progress: [
            null as string | null,
            {
                setProgress: (_, { progress }) => progress,
                kernelStarted: () => null,
                kernelFailed: () => null,
                stopKernel: () => null,
                runFinished: () => null,
            },
        ],
        canInterrupt: [
            false,
            {
                kernelStarted: (_, { canInterrupt }) => canInterrupt,
            },
        ],
        frames: [
            [] as BrowserKernelFrame[],
            {
                setFrames: (_, { frames }) => frames,
                restartKernel: () => [],
                stopKernel: () => [],
                kernelFailed: () => [],
            },
        ],
    }),
    selectors({
        isRunning: [
            (s) => [s.status],
            (status: BrowserKernelStatus): boolean => status === 'ready' || status === 'busy',
        ],
        outputFrameNames: [
            (s) => [s.frames],
            (frames: BrowserKernelFrame[]): Set<string> =>
                new Set(frames.filter((frame) => frame.origin === 'output').map((frame) => frame.name)),
        ],
    }),
    listeners(({ actions, cache, props }) => {
        const boot = (): void => {
            const startedAt = performance.now()
            const client = new BrowserKernelClient(
                (message) => actions.setProgress(message),
                (message) => {
                    if (cache.client === client) {
                        actions.kernelFailed(message)
                    }
                }
            )
            cache.client = client
            client.started.then(
                () => {
                    if (cache.client === client) {
                        posthog.capture('notebook browser kernel started', {
                            notebook_short_id: props.shortId,
                            duration_ms: Math.round(performance.now() - startedAt),
                            can_interrupt: client.canInterrupt,
                        })
                        actions.kernelStarted(client.canInterrupt)
                    }
                },
                (error: Error) => {
                    if (cache.client === client) {
                        posthog.capture('notebook browser kernel start failed', {
                            notebook_short_id: props.shortId,
                            duration_ms: Math.round(performance.now() - startedAt),
                            error: error.message,
                        })
                        client.terminate(error.message)
                        actions.kernelFailed(error.message)
                    }
                }
            )
        }
        return {
            startKernel: () => {
                if (!cache.client) {
                    boot()
                }
            },
            restartKernel: () => {
                ;(cache.client as BrowserKernelClient | undefined)?.terminate('The browser kernel restarted.')
                boot()
            },
            stopKernel: () => {
                ;(cache.client as BrowserKernelClient | undefined)?.terminate('The browser kernel stopped.')
                cache.client = null
            },
            kernelFailed: () => {
                cache.client = null
            },
        }
    }),
    beforeUnmount(({ cache }) => {
        ;(cache.client as BrowserKernelClient | undefined)?.terminate('The notebook closed.')
        cache.client = null
    }),
])

export async function ensureBrowserKernel(shortId: string): Promise<BrowserKernelClient> {
    const logic = notebookBrowserKernelLogic.findMounted({ shortId })
    if (!logic) {
        throw new Error('Open the notebook to run cells in your browser.')
    }
    logic.actions.startKernel()
    const client = logic.cache.client as BrowserKernelClient | null
    if (!client) {
        throw new Error(logic.values.error ?? 'The browser kernel could not start.')
    }
    await client.started
    return client
}

export function runningBrowserKernel(shortId: string): BrowserKernelClient | null {
    const logic = notebookBrowserKernelLogic.findMounted({ shortId })
    return logic?.values.isRunning ? ((logic.cache.client as BrowserKernelClient | null) ?? null) : null
}
